from pathlib import Path
import json
B=Path(__file__).parent;geo=json.load(open(B/'gaia-geometry.json'));dec={}
for tic in json.load(open(B/'targets-selected.json')):
 g=geo[tic];d=dict(verdict='CONFIRMED',assessment='Repeated discrete eclipses are remeasured in raw QLP flux with a coherent event-derived period. Fresh custom TESScut extraction recovers the deficit, and source tests favor the target against all catalogue neighbours capable under the conservative magnitude limit.',source='Signed difference images, Gaussian free-center diagnostics and fixed-coordinate target-versus-neighbour fits are preserved in raw-evidence. The fixed-position neighbour/target residual sums of squares consistently favor the target. Ratios are descriptive, not formal significance; source PRF mismatch is a limitation.',geometry='',limitations='No exhaustive event/sector fit or detailed binary model; custom extraction shares TESS photons; 60 arcsec TIC neighbour search and uncalibrated PRF systematics limit the source assessment.',next_check='Optional spectroscopy or higher spatial resolution photometry would refine characterization; no additional deciding gate is required by this representative review.')
 if 'gaia_P'in g:
  k=g['closest_kind'];c=g['conjunction'][k];d['geometry']=f"Photometric period {g['phot_P']:.9f} d versus Gaia {g['gaia_P']:.9f} ± {g['gaia_P_error']:.8f} d; difference {g['period_difference_gaia_sigma']:.2f} Gaia sigma. Nearest approximate conjunction {k}: offset {c['offset_d']:.3f} d; linear covariance error {c['covariance_linear_error_d']:.3f} d, conservative sum bound {c['conservative_sum_error_d']:.3f} d. Observed median duration {g['observed_duration_hours_median']:.2f} h versus approximate central feasibility {g['central_duration_hours_approx']:.2f} h. Phase uncertainty and approximate geometry are retained rather than treating a linear sigma as exact."
 if tic in ['376082142','251357000']:
  d.update(verdict='REFUTED',assessment='The original screen positive is smooth double-wave modulation, rather than an established discrete eclipse. Three QLP sector folds and four-harmonic residual diagnostics show no narrow residual recurring at the searched phase. This refutes the proposed eclipsing morphology at the measured signal; shallow additional eclipses are not excluded.',source='Fresh cutouts were obtained, but no eclipsing deficit is established to localize. Morphology is the deciding failure, not a missing pixel test. The smooth variable itself has not been assigned a by-catch host.',geometry='The doubled BLS interval follows the Gaia orbit approximately, but a modulation period is not an eclipse-derived period. No eclipse conjunction geometry is claimed.',limitations='No established eclipse; the smooth signal could be ellipsoidal or other variability. Harmonics can absorb broad events and do not prove absence of shallow eclipses.',next_check='Search higher precision data for a discrete narrow eclipse only if this smooth variable remains of interest.')
 if tic=='285942031':
  d.update(verdict='PROBABLE',assessment='Deep, repeated discrete eclipses are real and source fits favor the target in two detector sectors. The Gaia orbit has material timing tension, so the geometry check is not fully passed.',limitations='Gaia period differs by -3.78 sigma; approximate conjunction is 0.355 d off versus linear covariance error 0.074 d. The conservative sum error is 0.342 d; a nonlinear orbital posterior or fresh RV fit is needed before treating this as the Gaia eclipsing system.',next_check='Reassess Gaia orbital uncertainties/correlations or obtain an updated radial-velocity orbit to resolve the eclipse-versus-Gaia timing tension.')
 if tic=='281393563':
  d.update(verdict='PROBABLE',assessment='Repeated deep detached eclipses have a coherent event-derived period and feasible Gaia geometry. Fresh source imaging was attempted, but crowding prevents a secure target assignment.',source='Sectors 10 and64 contain target-region deficits; sector64 also has a strong off-center deficit. Fixed-position capable-neighbour alternatives have residual ratios only1.03–1.99, with a degenerate free-center fit. This is an unresolved source gate, not unattempted work.',limitations='The eclipses repeat, but the host is not separated from capable neighbours. Pixel models are degenerate in this crowded field.',next_check='Obtain higher resolution time-series imaging or a validated multi-source PRF difference fit to identify the eclipsing host.')
 if tic=='126363604':
  d.update(verdict='PROBABLE',assessment='Four sharp repeat eclipses are visible over a variable stellar baseline; all four centers define an eclipse period. Raw-event scatter is inflated by variability, so the initial depth/RMS gate was explicitly relaxed after fold inspection. Fresh imaging supports the target but does not fully exclude its closest capable source.',source='Four individual signed difference images in sectors7,61,88 place fitted deficits3.93,1.34,0.81,0.82 arcsec from the target. Nearest capable neighbour is11.14 arcsec. The first-sector fixed-source residual ratio is only1.78; repeat source positions support the target but the PSF systematics are uncalibrated. Custom extraction recovers repeated deficits in the same TESS photons.',limitations='Closest capable host not conclusively excluded under the source model; approximate Gaia conjunction offset0.657 d has linear covariance error0.290 d, with broad conservative uncertainty. Stellar variability affects local timing/depth.',next_check='Validate the repeated difference-image astrometry with a multi-source PRF or higher resolution event photometry; refine Gaia conjunction uncertainty if needed.')
 dec[tic]=d
(B/'decisions.json').write_text(json.dumps(dec,indent=2))
